        Some(auth),
        &body,
        Some(etag_before.as_str()),
    )
    .await;

    assert_eq!(status, StatusCode::OK);
    let etag_after = headers
        .get(header::ETAG)
        .unwrap()
        .to_str()
        .unwrap()
